command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: BLUTHEILUNG (Ausführung)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    let fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Blutheilung";
    const ahne = "brona"; 
    const finalEffektName = `${gabenName} (Brona)`;
    const iconBild = DSK_FW.Symbol(ahne);

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. CASTER ERMITTELN ---
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    const qs = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");
    let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    getOwners(casterActor).forEach(id => ownerIds.add(id));

    // --- 3. WÜRFELN & BERECHNEN ---
    const bonus = Math.ceil(qs / 2); // QS/2 wird aufgerundet
    const healRoll = await new Roll(`2d6 + ${bonus}`).evaluate({async: true});
    const healAmount = healRoll.total;

    // Die einzelnen Würfelergebnisse der 2W6 auslesen
    const wuerfelErgebnisse = healRoll.dice[0].results.map(r => r.result).join(" + ");

    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';

    // --- 4. ZIELE HOLEN (Target ODER sich selbst) ---
    let targets = Array.from(game.user.targets);
    if (targets.length === 0) {
        let controlled = canvas.tokens.controlled[0];
        if (controlled) targets = [controlled];
    }
    if (targets.length === 0) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle deinen Token oder ein Ziel aus!");

    // --- 5. HEILUNG ANWENDEN ---
    const erfolge = [];
    const fehler = [];

    for (let t of targets) {
        if (!t.actor) continue;

        const maxLeP = t.actor.system.stats.LeP.max;
        const currentLeP = t.actor.system.stats.LeP.value;

        if (currentLeP >= maxLeP) {
            fehler.push({ name: t.name, grund: "Bereits volle LeP" });
            continue;
        }

        let neueLeP = currentLeP + healAmount;
        let actualHeal = healAmount;
        if (neueLeP > maxLeP) {
            actualHeal = maxLeP - currentLeP;
            neueLeP = maxLeP;
        }

        await t.actor.update({"system.stats.LeP.value": neueLeP});
        erfolge.push({ name: t.name, amount: actualHeal, total: neueLeP, max: maxLeP });
    }

    // --- 6. FLAG-CLEANUP ---
    if (erfolge.length > 0 || fehler.length > 0) {
        await casterActor.unsetFlag("world", "letzteGabenQS");
        await casterActor.unsetFlag("world", "letzteGabenMessageId");
    }

    // --- 7. CHAT-KARTE BAUEN ---
    targets.forEach(t => {
        if(t?.actor) Object.entries(t.actor.ownership || {}).filter(([id, lvl]) => lvl === 3).forEach(([id]) => ownerIds.add(id));
    });

    const erfolgHtml = erfolge.length > 0 
        ? `<div style="margin-top: 10px; margin-bottom: 10px;">
               <p style="margin-bottom: 5px;"><span style="color:#18940F; font-weight:bold;">Blut absorbiert:</span></p>
               <ul class="dsklist" style="margin-top:0; font-weight:normal; color: #000;">
                   ${erfolge.map(e => `<li><b>${e.name}</b> <span style="color: #2e7d32;">(+${e.amount} LeP)</span> ➔ ${e.total}/${e.max}</li>`).join("")}
               </ul>
           </div>` : ``;

    const fehlschlagHtml = fehler.length > 0
        ? `<div style="margin-top: 10px; margin-bottom: 10px;">
               <p style="margin-bottom: 5px;"><span style="color:#B30000; font-weight:bold;">Fehlschlag:</span></p>
               <ul class="dsklist" style="margin-top:0; font-weight:normal; color: #000;">
                   ${fehler.map(f => `<li>${f.name} (${f.grund})</li>`).join("")}
               </ul>
           </div>` : ``;

    const cardContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p style="margin-bottom: 8px;"><b>Gabenwirkung:</b></p>
                <p style="margin-top:0; text-align: justify;">Der Vampir wandelt gesaugtes Blut in pure Lebensenergie um.</p>
                <div style="text-align:center; padding: 6px; background: rgba(0,0,0,0.03); border: 1px solid #c9bca6; border-radius: 4px; margin-bottom: 8px;">
                    <span style="font-size: 0.9em; color: #555;">Gewürfelte Heilung:</span><br>
                    <b style="color: #76301b; font-size: 1.2em;">${healAmount} LeP</b><br>
                    <span ${thinStyle}>Würfel: [${wuerfelErgebnisse}] + Bonus: ${bonus}<br>(2W6 + ${bonus} QS/2)</span>
                </div>
                ${erfolgHtml}
                ${fehlschlagHtml}
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: cardContent });
    } else {
        const neueMsg = await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: Array.from(ownerIds).filter(id => game.users.get(id)),
            content: cardContent
        });
        if (neueMsg && erfolge.length === 0 && fehler.length === 0) {
            await casterActor.setFlag("world", "letzteGabenMessageId", neueMsg.id);
        }
    }
})();
